// Tinos (Apache-2.0, Times metric-compatible) — executive template.
// LATIN-SUBSET (fontTools, ranges match arimo-fonts.ts), base64-bundled so the
// CV PDF renderer has NO runtime network fetch. Raw .ttf sources are gitignored;
// these base64 modules are the committed source the renderer loads.
//
// Per-file (subset):
//   TINOS_REGULAR: 80.4 KB
//   TINOS_BOLD: 86.5 KB
//   TINOS_ITALIC: 82.7 KB
//   TINOS_BOLDITALIC: 83.2 KB

const decode = (b64: string): Uint8Array =>
  Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

export const TINOS_REGULAR: Uint8Array = decode(
  "",
);
export const TINOS_BOLD: Uint8Array = decode(
  "",
);
export const TINOS_ITALIC: Uint8Array = decode(
  "",
);
export const TINOS_BOLDITALIC: Uint8Array = decode(
  "",
);
